use soroban_sdk::contracttype;
use sororail_common::impl_single_position_storage;

use crate::types::Authorization;

/// Storage keys for the recurring contract.
///
/// The whole authorization lives in **instance** storage, so it shares one
/// TTL with the contract. The enum has one variant because one instance holds
/// one authorization. It is typed so the key encodes the same way across every
/// SoroRail contract.
///
/// Access goes through the helpers generated by
/// `impl_single_position_storage!`, which extend the TTL on every write.
#[contracttype]
pub enum DataKey {
    /// The single authorization held by this instance.
    ///
    /// Holds the full [`Authorization`] record: payer, payee, token, the
    /// per-period cap, the cadence in seconds, `max_periods` and
    /// `periods_charged`, the next chargeable timestamp, and the cancelled
    /// flag. The token allowance itself is held by the token contract, not
    /// here. Absent until `authorize` runs, which is what
    /// `NotInitialized` reports.
    Auth,
}

impl_single_position_storage!(Authorization, DataKey::Auth);
